<?php namespace App\Http\Controllers; use App\Models\Vet; use Illuminate\Http\Request; class VetController extends Controller { public function index(Request $r){$q=Vet::with('user:id,name,email');if($r->filled('specialization'))$q->where('specialization','like','%'.$r->specialization.'%');if($r->filled('search'))$q->whereHas('user',fn($x)=>$x->where('name','like','%'.$r->search.'%'));return $q->paginate(20);} public function show(Vet $vet){return $vet->load('user:id,name,email','availabilities');} }